import { OpenCode } from "@opencode/client";
import { nativeEngineStatusSchema, type NativeEngineStatus } from "../../shared/contracts.ts";

export const FREE_DEEPSEEK_MODEL = "opencode/deepseek-v4.1-flash-free" as const;

export interface NativeClientOptions {
  baseUrl: string;
  REDACTED?: string;
}

export function createNativeClient(options: NativeClientOptions) {
  const authorization = options.REDACTED
    ? `Basic ${Buffer.from(`opencode:${options.REDACTED}`).toString("base64")}`
    : undefined;

  return OpenCode.make({
    baseUrl: options.baseUrl,
    headers: authorization ? { authorization } : undefined,
  });
}

export async function probeNativeEngine(options: NativeClientOptions): Promise<NativeEngineStatus> {
  try {
    const client = createNativeClient(options);
    const [server, models] = await Promise.all([
      client.server.info(),
      client.model.list(),
    ]);
    const modelAvailable = models.data.some((model) =>
      `${model.providerID}/${model.id}` === FREE_DEEPSEEK_MODEL,
    );

    return nativeEngineStatusSchema.parse({
      available: true,
      serverVersion: server.version,
      model: FREE_DEEPSEEK_MODEL,
      modelAvailable,
      limitation: modelAvailable ? null : "The required free DeepSeek model is not in the native catalog.",
    });
  } catch (error) {
    return nativeEngineStatusSchema.parse({
      available: false,
      serverVersion: null,
      model: FREE_DEEPSEEK_MODEL,
      modelAvailable: false,
      limitation: error instanceof Error ? error.message : "Native OpenCode is unavailable.",
    });
  }
}
import { randomUUID } from "node:crypto";
import { operationSchema, payloadHash, type Operation } from "../workflow/model.ts";

export function queueOperation(payload: unknown): Operation {
  return operationSchema.parse({
    id: randomUUID(),
    payloadHash: payloadHash(payload),
    nativeSessionId: null,
    nativeMessageId: null,
    status: "QUEUED",
    result: null,
  });
}

export function markDisconnected(operation: Operation): Operation {
  if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) return operation;
  return operationSchema.parse({ ...operation, status: "UNKNOWN", result: "Disconnected; reconcile native state before retry." });
}

export function reconcileOperation(
  operation: Operation,
  native: { sessionId: string; messageId?: string; status: "running" | "waiting_permission" | "succeeded" | "failed" | "cancelled"; result?: string },
): Operation {
  const statuses = {
    running: "RUNNING",
    waiting_permission: "WAITING_PERMISSION",
    succeeded: "SUCCEEDED",
    failed: "FAILED",
    cancelled: "CANCELLED",
  } as const;
  return operationSchema.parse({
    ...operation,
    nativeSessionId: native.sessionId,
    nativeMessageId: native.messageId ?? operation.nativeMessageId,
    status: statuses[native.status],
    result: native.result ?? null,
  });
}
