import { createNativeClient, FREE_DEEPSEEK_MODEL, type NativeClientOptions } from "../opencode/client.ts";
import {
  setOpenCodeResult,
  traceChatOperation,
  traceCreateAgent,
  traceToolOperation,
} from "./telemetry.ts";

export interface SpokenResult {
  sessionId: string;
  messageId: string | null;
  text: string;
  cost: number;
}

export interface PerformedResult extends SpokenResult {
  diff: string;
}

export interface SpiritGuide {
  speak(input: { role: "oracle" | "architect" | "witness"; conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<SpokenResult>;
  perform(input: { conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<PerformedResult>;
  inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown">;
}

const readOnlyPermissions = [
  { action: "edit", resource: "*", effect: "deny" as const },
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
];

const makerPermissions = [
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
  { action: "edit", resource: "*", effect: "allow" as const },
];

function assertFreeModel(model: { providerID: string; id: string } | undefined, cost: number): void {
  const selected = model ? `${model.providerID}/${model.id}` : "";
  if (selected !== FREE_DEEPSEEK_MODEL) {
    throw new Error("Native session left the required free DeepSeek model.");
  }
  if (cost > 0) throw new Error("Native session reported a non-zero cost.");
}

export class OpenCodeSpiritGuide implements SpiritGuide {
  constructor(private readonly options: NativeClientOptions) {}

  private client() {
    return createNativeClient(this.options);
  }

  private async openSession(role: "oracle" | "architect" | "maker" | "witness", conversationId: string, workspace: string, sessionId: string | null, permissions: Array<{ action: string; resource: string; effect: "allow" | "deny" | "ask" }>) {
    if (sessionId) return sessionId;
    return traceCreateAgent(role, conversationId, async (span) => {
      const created = await this.client().session.create({
        title: `Unfinished Business ${role}`,
        model: { providerID: "opencode", id: "deepseek-v4.1-flash-free" },
        location: { directory: workspace },
        permissions,
      });
      setOpenCodeResult(span, { sessionId: created.id });
      return created.id;
    });
  }

  async speak(input: { role: "oracle" | "architect" | "witness"; conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<SpokenResult> {
    return traceChatOperation(input.role, input.conversationId, async (span) => {
      const sessionId = await this.openSession(input.role, input.conversationId, input.workspace, input.sessionId, readOnlyPermissions);
      const generated = await this.client().session.generate({ sessionID: sessionId, prompt: input.prompt });
      let text = generated.text?.trim() ?? "";
      if (text.length < 80) {
        await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
        await Promise.race([
          this.client().session.wait({ sessionID: sessionId }),
          new Promise<never>((_, reject) => {
            setTimeout(() => reject(new Error("Native spirit timed out before it became idle.")), 90_000);
          }),
        ]);
        const listed = await this.client().message.list({ sessionID: sessionId, type: "assistant" });
        const messages = Array.isArray(listed) ? listed : listed.data;
        text = messages.flatMap((message) => message.type === "assistant" ? message.content : [])
          .flatMap((part) => part.type === "text" ? [part.text] : [])
          .join("\n")
          .trim();
      }
      const info = await this.client().session.get({ sessionID: sessionId });
      assertFreeModel(info.model, info.cost);
      if (!text) throw new Error("Native session returned no assistant text.");
      setOpenCodeResult(span, { sessionId, cost: info.cost });
      return { sessionId, messageId: null, text, cost: info.cost };
    });
  }

  async perform(input: { conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<PerformedResult> {
    return traceChatOperation("maker", input.conversationId, async (span) => {
      const sessionId = await this.openSession("maker", input.conversationId, input.workspace, input.sessionId, makerPermissions);
      const prompted = await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
      let timedOut = false;
      await Promise.race([
        this.client().session.wait({ sessionID: sessionId }),
        new Promise<void>((resolve) => {
          setTimeout(() => {
            timedOut = true;
            resolve();
          }, 180_000);
        }),
      ]);
      const info = await this.client().session.get({ sessionID: sessionId });
      assertFreeModel(info.model, info.cost);
      const diff = await traceToolOperation("maker", input.conversationId, "opencode.session.diff", async (toolSpan) => {
        const result = await this.client().session.diff({ sessionID: sessionId });
        setOpenCodeResult(toolSpan, { sessionId });
        toolSpan.setAttribute("opencode.diff.file_count", result.length);
        return result;
      });
      const summary = diff.length
        ? diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n")
        : timedOut
          ? "Native Maker run timed out before it became idle, without a file diff."
          : "Native session finished without a file diff.";
      const messageId = typeof prompted.id === "string" ? prompted.id : null;
      setOpenCodeResult(span, { sessionId, messageId, cost: info.cost });
      return { sessionId, messageId, text: summary, diff: summary, cost: info.cost };
    });
  }

  async inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown"> {
    return traceToolOperation(context.role, context.conversationId, "opencode.session.inspect", async (span) => {
      const info = await this.client().session.get({ sessionID: sessionId });
      setOpenCodeResult(span, { sessionId, cost: info.cost });
      if (info.outcome === "succeeded") return "succeeded";
      if (info.outcome === "failed" || info.outcome === "interrupted") return "failed";
      if (!info.time.idle) return "running";
      return "unknown";
    });
  }
}
import * as Sentry from "@sentry/hono/node";
import type { Span } from "@sentry/hono/node";
import { FREE_DEEPSEEK_MODEL } from "../opencode/client.ts";

type SpiritRole = "oracle" | "architect" | "maker" | "witness";

interface OpenCodeResultMetadata {
  sessionId?: string | null;
  messageId?: string | null;
  cost?: number;
}

const pipelineName = "unfinished-business";
const providerName = "opencode";

function baseAttributes(role: SpiritRole, conversationId: string) {
  return {
    "gen_ai.agent.name": role,
    "gen_ai.conversation.id": conversationId,
    "gen_ai.pipeline.name": pipelineName,
    "gen_ai.provider.name": providerName,
    "gen_ai.request.model": FREE_DEEPSEEK_MODEL,
  };
}

function safeSpanError(error: unknown): string {
  const message = error instanceof Error ? error.message : "";
  if (/timed out|timeout|abort/i.test(message)) return "deadline_exceeded";
  if (/ECONN|fetch|network|socket|unavailable/i.test(message)) return "unavailable";
  return "internal_error";
}

function traced<T>(
  options: Parameters<typeof Sentry.startSpan<T>>[0],
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return Sentry.startSpan(options, async (span) => {
    try {
      const result = await work(span);
      span.setStatus({ code: 1 });
      return result;
    } catch (error) {
      span.setStatus({ code: 2, message: safeSpanError(error) });
      throw error;
    }
  });
}

export function traceAgentOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `invoke_agent ${role}`,
    op: "gen_ai.invoke_agent",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "invoke_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceChatOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `chat ${FREE_DEEPSEEK_MODEL}`,
    op: "gen_ai.chat",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "chat",
      "gen_ai.operation.type": "ai_client",
    },
  }, work);
}

export function traceCreateAgent<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `create_agent ${role}`,
    op: "gen_ai.create_agent",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "create_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceToolOperation<T>(
  role: SpiritRole,
  conversationId: string,
  toolName: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `execute_tool ${toolName}`,
    op: "gen_ai.execute_tool",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "execute_tool",
      "gen_ai.operation.type": "tool",
      "gen_ai.tool.name": toolName,
    },
  }, work);
}

export function setOpenCodeResult(span: Span, metadata: OpenCodeResultMetadata): void {
  span.setAttribute("gen_ai.response.model", FREE_DEEPSEEK_MODEL);
  if (metadata.sessionId) span.setAttribute("opencode.session.id", metadata.sessionId);
  if (metadata.messageId) span.setAttribute("gen_ai.response.id", metadata.messageId);
  if (typeof metadata.cost === "number" && Number.isFinite(metadata.cost)) {
    span.setAttribute("gen_ai.cost.total_tokens", metadata.cost);
  }
}

import { createHash, randomUUID } from "node:crypto";
import { z } from "zod";

export const sectionStatusSchema = z.enum(["NOT_STARTED", "DRAFT", "APPROVED", "STALE"]);
export const operationStatusSchema = z.enum([
  "QUEUED", "RUNNING", "WAITING_PERMISSION", "SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN",
]);

export const sectionSchema = z.object({
  id: z.string(),
  title: z.string(),
  order: z.number().int().positive(),
  dependencies: z.array(z.string()),
  content: z.string(),
  version: z.number().int().nonnegative(),
  hash: z.string(),
  status: sectionStatusSchema,
});

export const approvalSchema = z.object({
  id: z.string(),
  sectionId: z.string(),
  version: z.number().int().positive(),
  hash: z.string(),
  approvedAt: z.string(),
  staleReason: z.string().nullable(),
});

export const actionSchema = z.object({
  id: z.string(),
  payloadHash: z.string(),
  resultRevision: z.number().int().nonnegative(),
});

export const operationSchema = z.object({
  id: z.string(),
  kind: z.enum(["guide", "maker", "witness", "check"]).default("guide"),
  payloadHash: z.string(),
  nativeSessionId: z.string().nullable(),
  nativeMessageId: z.string().nullable(),
  status: operationStatusSchema,
  result: z.string().nullable(),
});

export const evidenceSchema = z.object({
  id: z.string(),
  checkId: z.string(),
  nativeResultReference: z.string(),
  testedFingerprint: z.string(),
  result: z.enum(["PASS", "FAIL", "NOT_RUN", "INCONCLUSIVE", "STALE"]),
  observedAt: z.string(),
  limitation: z.string().nullable(),
});

export const productSchema = z.object({
  status: z.enum(["NONE", "PROPOSED", "APPROVED"]).default("NONE"),
  proposal: z.string().nullable().default(null),
  openQuestions: z.array(z.string()).default([]),
});

export const makerScopeSchema = z.object({
  status: z.enum(["NONE", "GRANTED"]).default("NONE"),
  statement: z.string().nullable().default(null),
});

export const transcriptEntrySchema = z.object({
  id: z.string(),
  spirit: z.enum(["user", "oracle", "architect", "maker", "witness", "system"]),
  text: z.string(),
  createdAt: z.string(),
});

export const capabilitySchema = z.object({
  id: z.string(),
  purpose: z.string(),
  nativeMapping: z.string(),
  availability: z.enum(["available", "unavailable", "unknown"]),
  permission: z.string(),
  observedOutcome: z.string().nullable(),
});

export const witnessDraftSchema = z.object({
  id: z.string(),
  title: z.string(),
  content: z.string(),
  nativeSessionId: z.string().nullable(),
});

export const nativeSessionRefSchema = z.object({
  role: z.enum(["oracle", "architect", "maker", "witness"]),
  sessionId: z.string(),
});

export const projectSchema = z.object({
  schemaVersion: z.literal(1),
  id: z.string(),
  revision: z.number().int().nonnegative(),
  workspace: z.string(),
  stage: z.enum(["ORACLE", "ARCHITECT", "MAKER", "WITNESS"]),
  currentSectionId: z.string().nullable(),
  sections: z.array(sectionSchema),
  approvals: z.array(approvalSchema),
  actions: z.array(actionSchema),
  operations: z.array(operationSchema),
  evidence: z.array(evidenceSchema),
  nextAction: z.string(),
  product: productSchema.default({ status: "NONE", proposal: null, openQuestions: [] }),
  makerScope: makerScopeSchema.default({ status: "NONE", statement: null }),
  transcript: z.array(transcriptEntrySchema).default([]),
  capabilities: z.array(capabilitySchema).default([]),
  witnessDrafts: z.array(witnessDraftSchema).default([]),
  nativeSessions: z.array(nativeSessionRefSchema).default([]),
});

export type Project = z.infer<typeof projectSchema>;
export type PlanSection = z.infer<typeof sectionSchema>;
export type Operation = z.infer<typeof operationSchema>;
export type Capability = z.infer<typeof capabilitySchema>;
export type SpiritRole = "oracle" | "architect" | "maker" | "witness";

const sectionDefinitions = [
  ["control", "Control, product, scope, and acceptance", []],
  ["architecture", "Architecture and contracts", ["control"]],
  ["experience", "Experience", ["control", "architecture"]],
  ["tools", "Tools, access, and cost", ["architecture"]],
  ["verification", "Verification and risks", ["control", "architecture", "tools"]],
  ["phases", "Phases and queue", ["verification"]],
  ["delivery", "Delivery", ["experience", "verification", "phases"]],
  ["readiness", "Execution directive and readiness", ["control", "architecture", "experience", "tools", "verification", "phases", "delivery"]],
] as const;

export function contentHash(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}

export function payloadHash(payload: unknown): string {
  return contentHash(JSON.stringify(payload, Object.keys(payload as object).sort()));
}

export function createProject(workspace: string): Project {
  const sections = sectionDefinitions.map(([id, title, dependencies], index) => ({
    id,
    title,
    order: index + 1,
    dependencies: [...dependencies],
    content: "",
    version: 0,
    hash: contentHash(""),
    status: "NOT_STARTED" as const,
  }));
  return refreshNextAction(projectSchema.parse({
    schemaVersion: 1,
    id: randomUUID(),
    revision: 0,
    workspace,
    stage: "ORACLE",
    currentSectionId: sections[0].id,
    sections,
    approvals: [],
    actions: [],
    operations: [],
    evidence: [],
    nextAction: "Describe an idea and wake the Oracle",
    product: { status: "NONE", proposal: null, openQuestions: [] },
    makerScope: { status: "NONE", statement: null },
    transcript: [],
    capabilities: [
      {
        id: "inspect-changes",
        purpose: "Show the diff from the Maker's native session",
        nativeMapping: "OpenCode session.diff in the isolated demo workspace",
        availability: "unknown",
        permission: "Read-only inspection after a Maker run",
        observedOutcome: null,
      },
      {
        id: "node-check",
        purpose: "Run the approved dependency-free Node test",
        nativeMapping: "bounded node --test in the isolated demo workspace",
        availability: "available",
        permission: "Runs only after an explicit Maker scope grant and a native edit",
        observedOutcome: null,
      },
    ],
    witnessDrafts: [],
    nativeSessions: [],
  }));
}

export function refreshNextAction(project: Project): Project {
  const current = project.sections.find((section) => section.status !== "APPROVED") ?? null;
  project.currentSectionId = current?.id ?? null;
  if (project.product.status !== "APPROVED") {
    project.stage = "ORACLE";
    project.nextAction = project.product.status === "PROPOSED"
      ? "Approve the Oracle proposal, or ask a question"
      : "Describe an idea and wake the Oracle";
    return project;
  }
  if (current) {
    project.stage = "ARCHITECT";
    project.nextAction = `${current.status === "DRAFT" || current.status === "STALE" ? "Review" : "Draft"} ${current.title}`;
    return project;
  }
  if (project.makerScope.status !== "GRANTED") {
    project.stage = "ARCHITECT";
    project.nextAction = "Grant a separate Maker execution scope";
    return project;
  }
  const makerSucceeded = project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
  if (!makerSucceeded) {
    project.stage = "MAKER";
    project.nextAction = "Run the approved Maker unit and inspect the result";
    return project;
  }
  project.stage = "WITNESS";
  project.nextAction = project.witnessDrafts.length
    ? "Review the Witness drafts"
    : "Ask the Witness to review the evidence";
  return project;
}

:root {
  color: #f4f0e8;
  background: #111018;
  font-family: ui-sans-serif, system-ui, sans-serif;
  --bg: #111018;
  --surface: #1b1824;
  --raised: #252031;
  --text: #f4f0e8;
  --muted: #b8afca;
  --accent: #f4b66c;
  --spirit: #bfa3ff;
  --success: #8bd5a7;
  --danger: #ffb4a8;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 20% 0%, rgb(244 182 108 / 16%), transparent 28rem),
    var(--bg);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-style: solid;
  outline-offset: 3px;
  box-shadow: 0 0 0 3px var(--accent);
}

.skip {
  position: absolute;
  left: var(--space-4);
  top: -4rem;
  background: var(--accent);
  color: #111018;
  padding: var(--space-2) var(--space-3);
}

.skip:focus {
  top: var(--space-3);
}

.workshop {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--space-4);
  width: min(1120px, calc(100% - 32px));
  margin: var(--space-5) auto var(--space-6);
}

.stage-strip,
.side,
.document,
.panel {
  background: var(--surface);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 16px;
}

.stage-strip {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  padding: var(--space-3);
}

.stage {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-height: 44px;
  border: 0;
  border-radius: 999px;
  padding: var(--space-2) var(--space-3);
  background: transparent;
  color: var(--muted);
  font: inherit;
}

.stage[aria-current="step"] {
  background: var(--raised);
  color: var(--accent);
}

.stage.done {
  color: var(--success);
}

.lantern {
  width: 28px;
  height: 28px;
  flex: none;
}

.document {
  padding: var(--space-5);
  min-width: 0;
}

.eyebrow {
  margin: 0;
  color: var(--spirit);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2 {
  font-family: Georgia, "Iowan Old Style", serif;
  font-weight: 500;
}

h1 {
  margin: var(--space-2) 0 var(--space-4);
  color: var(--accent);
  font-size: clamp(2rem, 6vw, 3.5rem);
  line-height: 1.05;
  overflow-wrap: anywhere;
}

h2 {
  margin: 0 0 var(--space-2);
  font-size: 1.4rem;
}

.status-line,
.note,
label,
.side li,
.meta {
  color: var(--muted);
}

label {
  display: grid;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

textarea,
button.action,
.side button {
  font: inherit;
}

textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 7rem;
  resize: vertical;
  border-radius: 12px;
  border: 1px solid rgb(184 175 202 / 40%);
  background: var(--bg);
  color: var(--text);
  padding: var(--space-3);
  overflow-wrap: anywhere;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

.action {
  min-height: 44px;
  border: 0;
  border-radius: 999px;
  padding: var(--space-2) var(--space-4);
  background: var(--accent);
  color: #23180d;
  font-weight: 650;
}

.action.secondary {
  background: var(--raised);
  color: var(--text);
}

.action:disabled {
  opacity: 0.55;
}

.banner {
  margin-top: var(--space-4);
  padding: var(--space-3);
  border-radius: 12px;
  background: var(--raised);
  overflow-wrap: anywhere;
}

.banner.bad {
  color: var(--danger);
}

.banner.good {
  color: var(--success);
}

.prose,
.evidence {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.reading {
  max-height: 70vh;
  overflow: auto;
  padding-right: var(--space-2);
}

.seal {
  display: inline-block;
  margin-left: var(--space-2);
  color: var(--success);
}

.side {
  display: grid;
  gap: var(--space-4);
  align-content: start;
}

.panel {
  padding: var(--space-4);
  min-width: 0;
}

.panel ol,
.panel ul {
  margin: var(--space-3) 0 0;
  padding-left: 1.1rem;
}

.ghost {
  outline: 1px dashed var(--spirit);
  outline-offset: 2px;
}

.meta {
  font-family: ui-monospace, monospace;
  font-size: 0.85rem;
}

@media (min-width: 960px) {
  .workshop {
    grid-template-columns: minmax(0, 1fr);
  }

  .frame {
    display: grid;
    grid-template-columns: 220px minmax(0, 1fr) 280px;
    gap: var(--space-4);
    align-items: start;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .lantern .flame {
    transform-origin: center;
    animation: flicker 2.8s ease-in-out infinite;
  }
}

@keyframes flicker {
  50% { opacity: 0.72; }
}

@media (prefers-contrast: more) {
  .document,
  .panel,
  .stage-strip,
  textarea {
    border-width: 2px;
    border-color: var(--text);
  }
}

@media (forced-colors: active) {
  .action,
  .stage {
    border: 1px solid ButtonText;
  }

  .lantern {
    forced-color-adjust: auto;
  }
}

import { createNativeClient, FREE_DEEPSEEK_MODEL, type NativeClientOptions } from "../opencode/client.ts";
import {
  setOpenCodeResult,
  traceChatOperation,
  traceCreateAgent,
  traceToolOperation,
} from "./telemetry.ts";

export interface SpokenResult {
  sessionId: string;
  messageId: string | null;
  text: string;
  cost: number;
}

export interface PerformedResult extends SpokenResult {
  diff: string;
}

export interface SpiritGuide {
  speak(input: { role: "oracle" | "architect" | "witness"; conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<SpokenResult>;
  perform(input: { conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<PerformedResult>;
  inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown">;
}

const readOnlyPermissions = [
  { action: "edit", resource: "*", effect: "deny" as const },
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
];

const makerPermissions = [
  { action: "shell", resource: "*", effect: "deny" as const },
  { action: "external_directory", resource: "*", effect: "deny" as const },
  { action: "edit", resource: "*", effect: "allow" as const },
];

function assertFreeModel(model: { providerID: string; id: string } | undefined, cost: number): void {
  const selected = model ? `${model.providerID}/${model.id}` : "";
  if (selected !== FREE_DEEPSEEK_MODEL) {
    throw new Error("Native session left the required free DeepSeek model.");
  }
  if (cost > 0) throw new Error("Native session reported a non-zero cost.");
}

export class OpenCodeSpiritGuide implements SpiritGuide {
  constructor(private readonly options: NativeClientOptions) {}

  private client() {
    return createNativeClient(this.options);
  }

  private async openSession(role: "oracle" | "architect" | "maker" | "witness", conversationId: string, workspace: string, sessionId: string | null, permissions: Array<{ action: string; resource: string; effect: "allow" | "deny" | "ask" }>) {
    if (sessionId) return sessionId;
    return traceCreateAgent(role, conversationId, async (span) => {
      const created = await this.client().session.create({
        title: `Unfinished Business ${role}`,
        model: { providerID: "opencode", id: "deepseek-v4.1-flash-free" },
        location: { directory: workspace },
        permissions,
      });
      setOpenCodeResult(span, { sessionId: created.id });
      return created.id;
    });
  }

  async speak(input: { role: "oracle" | "architect" | "witness"; conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<SpokenResult> {
    return traceChatOperation(input.role, input.conversationId, async (span) => {
      const sessionId = await this.openSession(input.role, input.conversationId, input.workspace, input.sessionId, readOnlyPermissions);
      const generated = await this.client().session.generate({ sessionID: sessionId, prompt: input.prompt });
      let text = generated.text?.trim() ?? "";
      if (text.length < 80) {
        await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
        await Promise.race([
          this.client().session.wait({ sessionID: sessionId }),
          new Promise<never>((_, reject) => {
            setTimeout(() => reject(new Error("Native spirit timed out before it became idle.")), 90_000);
          }),
        ]);
        const listed = await this.client().message.list({ sessionID: sessionId, type: "assistant" });
        const messages = Array.isArray(listed) ? listed : listed.data;
        text = messages.flatMap((message) => message.type === "assistant" ? message.content : [])
          .flatMap((part) => part.type === "text" ? [part.text] : [])
          .join("\n")
          .trim();
      }
      const info = await this.client().session.get({ sessionID: sessionId });
      assertFreeModel(info.model, info.cost);
      if (!text) throw new Error("Native session returned no assistant text.");
      setOpenCodeResult(span, { sessionId, cost: info.cost });
      return { sessionId, messageId: null, text, cost: info.cost };
    });
  }

  async perform(input: { conversationId: string; sessionId: string | null; prompt: string; workspace: string }): Promise<PerformedResult> {
    return traceChatOperation("maker", input.conversationId, async (span) => {
      const sessionId = await this.openSession("maker", input.conversationId, input.workspace, input.sessionId, makerPermissions);
      const prompted = await this.client().session.prompt({ sessionID: sessionId, text: input.prompt });
      let timedOut = false;
      await Promise.race([
        this.client().session.wait({ sessionID: sessionId }),
        new Promise<void>((resolve) => {
          setTimeout(() => {
            timedOut = true;
            resolve();
          }, 180_000);
        }),
      ]);
      const info = await this.client().session.get({ sessionID: sessionId });
      assertFreeModel(info.model, info.cost);
      const diff = await traceToolOperation("maker", input.conversationId, "opencode.session.diff", async (toolSpan) => {
        const result = await this.client().session.diff({ sessionID: sessionId });
        setOpenCodeResult(toolSpan, { sessionId });
        toolSpan.setAttribute("opencode.diff.file_count", result.length);
        return result;
      });
      const summary = diff.length
        ? diff.map((file) => `${file.status} ${file.file} (+${file.additions}/-${file.deletions})`).join("\n")
        : timedOut
          ? "Native Maker run timed out before it became idle, without a file diff."
          : "Native session finished without a file diff.";
      const messageId = typeof prompted.id === "string" ? prompted.id : null;
      setOpenCodeResult(span, { sessionId, messageId, cost: info.cost });
      return { sessionId, messageId, text: summary, diff: summary, cost: info.cost };
    });
  }

  async inspect(sessionId: string, context: { conversationId: string; role: "oracle" | "architect" | "maker" | "witness" }): Promise<"running" | "succeeded" | "failed" | "unknown"> {
    return traceToolOperation(context.role, context.conversationId, "opencode.session.inspect", async (span) => {
      const info = await this.client().session.get({ sessionID: sessionId });
      setOpenCodeResult(span, { sessionId, cost: info.cost });
      if (info.outcome === "succeeded") return "succeeded";
      if (info.outcome === "failed" || info.outcome === "interrupted") return "failed";
      if (!info.time.idle) return "running";
      return "unknown";
    });
  }
}
import * as Sentry from "@sentry/hono/node";
import type { Span } from "@sentry/hono/node";
import { FREE_DEEPSEEK_MODEL } from "../opencode/client.ts";

type SpiritRole = "oracle" | "architect" | "maker" | "witness";

interface OpenCodeResultMetadata {
  sessionId?: string | null;
  messageId?: string | null;
  cost?: number;
}

const pipelineName = "unfinished-business";
const providerName = "opencode";

function baseAttributes(role: SpiritRole, conversationId: string) {
  return {
    "gen_ai.agent.name": role,
    "gen_ai.conversation.id": conversationId,
    "gen_ai.pipeline.name": pipelineName,
    "gen_ai.provider.name": providerName,
    "gen_ai.request.model": FREE_DEEPSEEK_MODEL,
  };
}

function safeSpanError(error: unknown): string {
  const message = error instanceof Error ? error.message : "";
  if (/timed out|timeout|abort/i.test(message)) return "deadline_exceeded";
  if (/ECONN|fetch|network|socket|unavailable/i.test(message)) return "unavailable";
  return "internal_error";
}

function traced<T>(
  options: Parameters<typeof Sentry.startSpan<T>>[0],
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return Sentry.startSpan(options, async (span) => {
    try {
      const result = await work(span);
      span.setStatus({ code: 1 });
      return result;
    } catch (error) {
      span.setStatus({ code: 2, message: safeSpanError(error) });
      throw error;
    }
  });
}

export function traceAgentOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `invoke_agent ${role}`,
    op: "gen_ai.invoke_agent",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "invoke_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceChatOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `chat ${FREE_DEEPSEEK_MODEL}`,
    op: "gen_ai.chat",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "chat",
      "gen_ai.operation.type": "ai_client",
    },
  }, work);
}

export function traceCreateAgent<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `create_agent ${role}`,
    op: "gen_ai.create_agent",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "create_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceToolOperation<T>(
  role: SpiritRole,
  conversationId: string,
  toolName: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
